1	import Phaser from "phaser";
2	import { milestoneFeedText } from "./restaurant-arena-milestones.js";
3	import { arenaBrief } from "./restaurant-arena-brief.js";
4	import {
5	  initOutcomeToastState,
6	  updateOutcomeToastState,
7	  type OutcomeToastState,
8	} from "./restaurant-arena-toast.js";
9	
10	export type { OutcomeToastState } from "./restaurant-arena-toast.js";
11	
12	/**
13	 * Supersampling factor for the canvas backing store. `mountRestaurantArenaScene`
14	 * boots the Phaser game at `cssSize * DPR` and `RestaurantArenaScene` zooms its
15	 * camera by the same factor, so world content authored in CSS-pixel units (see
16	 * `RestaurantArenaScene.cssWidth`/`cssHeight`) fills the larger backing store
17	 * instead of rendering small in a corner of it. Both sides have to move
18	 * together — see the comment on `RestaurantArenaScene.dpr` for the failure
19	 * mode when they don't. Capped at 2 so a 3x phone screen doesn't triple the
20	 * fill-rate cost for no visible gain.
21	 */
22	 const DPR = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, 2);
23	
24	export type Role = "host" | "supply_lead" | "chef" | "server" | "expediter";
25	type Location = "floor" | "kitchen" | "pass" | "queue";
26	type OrderStatus = "queued" | "seated" | "preparing" | "ready" | "served" | "cancelled";
27	export type RestaurantArenaWorkerStatus = "idle" | "thinking" | "acting" | "error";
28	
29	export interface RestaurantArenaState {
30	  episode: { tick: number; maxTicks: number };
31	  clock: { minute: number };
32	  tables: { id: string; seats: number; status: "empty" | "occupied"; orderId?: string }[];
33	  orders: { id: string; tableId?: string; items: string[]; status: OrderStatus; allergy?: string; priority: "normal" | "high" }[];
34	  inventory: Record<string, number>;
35	  equipment: { id: string; kind: "oven" | "warming_shelf"; status: "working" | "failed" | "degraded" }[];
36	  workers: { id: string; role: Role; location: Location; load: number }[];
37	  emergency?: { kind: string; active: boolean; startedAt: number };
38	  seatingHeld?: boolean;
39	  reputation?: number;
40	  outcomes: { cash: number; satisfaction: number; waste: number; completed: number };
41	  /** Present once the game exposes its playable layer; absent in raw fixtures. */
42	  sim?: { started: boolean; running: boolean; speed: number };
43	  feed?: { id: number; clock: string; who: string; voice: string; kind: string; text: string }[];
44	  waiting?: { id: string; size: number; patience: number; waitedTicks: number }[];
45	  decision?: {
46	    id: string;
47	    title: string;
48	    speaker: string;
49	    speakerRole: Role;
50	    prompt: string;
51	    options: { id: string; label: string; detail: string; tone: "safe" | "risky" | "neutral" }[];
52	  };
53	  staff?: Record<Role, { name: string; title: string; trait: string }>;
54	  goal?: { cash: number; maxWalkouts: number; unsafeAllowed: number };
55	  shift?: { id: string; title: string };
56	  upgrade?: { id: string; label: string; cost: number; bought: boolean };
57	  /** The receipt for the most recently answered decision, if any yet. */
58	  lastOutcome?: { id: string; headline: string; tone: "safe" | "risky" | "neutral" };
59	  coach?: { step: number; total: number; title: string; detail: string };
60	  /** Running fail-condition counters, for the manager brief. */
61	  tally?: { walkouts: number; unsafeServed: number };
62	}
63	
64	type ArenaRect = { x: number; y: number; width: number; height: number };
65	
66	interface RestaurantArenaLayout {
67	  compact: boolean;
68	  feedBeside: boolean;
69	  topBar: ArenaRect;
70	  brief: ArenaRect;
71	  kitchen: ArenaRect;
72	  pass: ArenaRect;
73	  dining: ArenaRect;
74	  door: ArenaRect;
75	  doorStand: ArenaRect;
76	  waypoints: Record<Location, { x: number; y: number }>;
77	  tickets: ArenaRect;
78	  feed: ArenaRect;
79	}
80	
81	function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
82	  const w = Math.max(320, width);
83	  const h = Math.max(240, height);
84	  const compact = false;
85	  const gap = 6;
86	  const margin = 8;
87	
88	  const topBarHeight = 38;
89	  const briefHeight = 32;
90	  const ticketsHeight = 72;
91	  const feedBeside = false;
92	  const feedHeight = Math.max(110, Math.round(h * 0.2));
93	
94	  const bodyX = margin;
95	  const briefY = margin + topBarHeight + gap;
96	  const bodyY = briefY + briefHeight + gap;
97	  const bodyWidth = w - margin * 2;
98	  const bodyBottom = h - margin - (feedHeight + gap);
99	  const bodyHeight = Math.max(120, bodyBottom - bodyY);
100	
101	  const floorHeight = Math.max(90, bodyHeight - ticketsHeight - gap);
102	
103	  const kitchenWidth = Math.round(bodyWidth * 0.25);
104	  const passWidth = Math.max(24, Math.round(bodyWidth * 0.07));
105	  const diningX = bodyX + kitchenWidth + gap + passWidth + gap;
106	  const diningWidth = Math.max(80, bodyX + bodyWidth - diningX);
107	  const doorHeight = Math.max(56, Math.round(floorHeight * 0.32));
108	  const diningHeight = floorHeight - doorHeight - gap;
109	
110	  const kitchen = { x: bodyX, y: bodyY, width: kitchenWidth, height: floorHeight };
111	  const pass = { x: bodyX + kitchenWidth + gap, y: bodyY, width: passWidth, height: floorHeight };
112	  const dining = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
113	  const door = { x: diningX, y: bodyY + diningHeight + gap, width: diningWidth, height: doorHeight };
114	  const labelH = 14;
115	  const hostGutter = 40;
116	  const standWidth = Math.min(90, Math.max(56, Math.round(door.width * 0.36)));
117	  const standHeight = Math.min(36, Math.max(22, door.height - labelH - 4));
118	  const doorStand = {
119	    x: door.x + hostGutter,
120	    y: door.y + labelH,
121	    width: standWidth,
122	    height: standHeight,
123	  };
124	  const waypoints: Record<Location, { x: number; y: number }> = {
125	    kitchen: { x: kitchen.x + kitchen.width / 2, y: kitchen.y + kitchen.height / 2 },
126	    pass: { x: pass.x + pass.width / 2, y: pass.y + pass.height / 2 },
127	    floor: { x: dining.x + dining.width / 2, y: dining.y + dining.height / 2 },
128	    queue: { x: door.x + door.width / 2, y: door.y + door.height / 2 },
129	  };
130	
131	  return {
132	    compact,
133	    feedBeside,
134	    topBar: { x: margin, y: margin, width: w - margin * 2, height: topBarHeight },
135	    brief: { x: margin, y: briefY, width: w - margin * 2, height: briefHeight },
136	    kitchen,
137	    pass,
138	    dining,
139	    door,
140	    doorStand,
141	    waypoints,
142	    tickets: { x: bodyX, y: bodyY + floorHeight + gap, width: bodyWidth, height: ticketsHeight },
143	    feed: { x: margin, y: bodyBottom + gap, width: w - margin * 2, height: feedHeight },
144	  };
145	}
146	
147	const COLORS = {
148	  ink: 0x241b14,
149	  panel: 0x2f241a,
150	  cream: 0xfff3d6,
151	  kitchen: 0xc9dbd2,
152	  kitchenDark: 0x4f796f,
153	  dining: 0xecc9a8,
154	  wood: 0xb9814f,
155	  pass: 0xf2cc5c,
156	  door: 0xa8c6da,
157	  empty: 0xc7ab86,
158	  occupied: 0xe8825f,
159	  working: 0x3d9b6d,
160	  failed: 0xc73535,
161	  ticket: 0xfff8e7,
162	  loadOk: 0x3d9b6d,
163	  loadWarn: 0xe08b2c,
164	  loadHot: 0xc73535,
165	  alert: 0xc73535,
166	  muted: 0x8d8378,
167	} as const;
168	
169	const ROLE_COLORS: Record<Role, number> = {
170	  host: 0x9763bd,
171	  supply_lead: 0xe69b2e,
172	  chef: 0xe44f3f,
173	  server: 0x3d73bf,
174	  expediter: 0xe69b2e,
175	};
176	
177	const STATUS_COLORS: Record<OrderStatus, number> = {
178	  queued: 0x8d8378,
179	  seated: 0x6f8fb5,
180	  preparing: 0xe08b2c,
181	  ready: 0x3d9b6d,
182	  served: 0x4f796f,
183	  cancelled: 0xc73535,
184	};
185	
186	const VOICE_COLORS: Record<string, string> = {
187	  host: "#c79bea",
188	  supply_lead: "#f4bf6a",
189	  chef: "#ff8f80",
190	  server: "#8ab6ef",
191	  expediter: "#f4bf6a",
192	  house: "#c9bdae",
193	  you: "#7ddc9f",
194	};
195	
196	const MONO = 'ui-monospace, "SF Mono", Menlo, monospace';
197	/** Spoken lines — a person talking, not a log. */
198	const DISPLAY = '"Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif';
199	/** Buttons, names, UI copy. */
200	const SANS = '"Avenir Next", "Segoe UI", "Helvetica Neue", system-ui, sans-serif';
201	
202	const DEFAULT_STAFF: Record<Role, { name: string; title: string; trait: string }> = {
203	  host: { name: "Host", title: "Host", trait: "" },
204	  supply_lead: { name: "Supply Lead", title: "Supply Lead", trait: "" },
205	  chef: { name: "Chef", title: "Chef", trait: "" },
206	  server: { name: "Server", title: "Server", trait: "" },
207	  get expediter() {
208	    return this.supply_lead;
209	  },
210	};
211	
212	function clockLabel(minute: number): string {
213	  const total = 17 * 60 + 30 + Math.max(0, Math.round(minute));
214	  return `${String(Math.floor(total / 60) % 24).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
215	}
216	
217	function loadColor(load: number): number {
218	  if (load > 0.8) return COLORS.loadHot;
219	  if (load >= 0.5) return COLORS.loadWarn;
220	  return COLORS.loadOk;
221	}
