360	  create(): void {
361	    // Every state change repaints from scratch, which destroys the zone the
362	    // cursor is sitting on and builds a new one in its place. Phaser only
363	    // re-tests what is under a *stationary* pointer when the pointer moves,
364	    // so without polling the second of two clicks on the same button — speed
365	    // 1x→2x→4x, most obviously — lands on nothing and is silently dropped.
366	    this.input.setPollAlways();
367	    this.patchTextResolution();
368	    this.applyHiDpi();
369	    this.paint();
370	    // The stage can still be settling when Phaser boots, and a paint sized off
371	    // a half-laid-out parent leaves a blank canvas until something resizes it.
372	    // There's no further "resize" event to catch that later, on purpose —
373	    // see `mountRestaurantArenaScene`, which tears down and boots a fresh
374	    // scene for any genuine later resize rather than mutating a live one.
375	    this.time.delayedCall(0, () => {
376	      this.applyHiDpi();
377	      this.paint();
378	    });
379	  }
380	
381	  /**
382	   * `Text` game objects rasterize to their own offscreen canvas at
383	   * `style.resolution`, which Phaser hardcodes to 1 unless a caller sets it
384	   * — independent of the backing-store fix below. Left alone, every label
385	   * would still upscale-blur once the camera zooms in to fill the bigger
386	   * backing store. Patching the factory here means every existing
387	   * `this.add.text(...)` call site downstream stays untouched.
388	   */
389	  private patchTextResolution(): void {
390	    const dpr = this.dpr;
391	    const originalText = this.add.text.bind(this.add);
392	    this.add.text = ((x: number, y: number, content: string | string[], style?: Phaser.Types.GameObjects.Text.TextStyle) =>
393	      originalText(x, y, content, { resolution: dpr, ...style })) as typeof this.add.text;
394	  }
395	
396	  /**
397	   * The canvas is already booted at `dpr` × the CSS size (see `dpr` above
398	   * and `mountRestaurantArenaScene`), so the backing store, renderer and
399	   * camera dimensions are already right — Phaser set them up that way at
400	   * construction and none of them are touched again here. What's left is
401	   * purely cosmetic: shrink the canvas' *displayed* CSS box back down to
402	   * its intended footprint (a style change, not a resize), and zoom the
403	   * camera so world content — authored in CSS-pixel units via `cssWidth`/
404	   * `cssHeight` — fills the larger backing store instead of rendering
405	   * small in its top-left corner.
406	   */
407	  private applyHiDpi(): void {
408	    const canvas = this.game.canvas;
409	    canvas.style.width = `${this.cssWidth}px`;
410	    canvas.style.height = `${this.cssHeight}px`;
411	    // A Phaser camera zooms around its own center, not the world origin —
412	    // at zoom 1 that's invisible (center and origin coincide when the
413	    // viewport already matches the content), but zooming in without
414	    // recentering shows the viewport's *center* region of world space, not
415	    // its top-left. Content here is authored from (0,0), so without this the
416	    // camera looks at world space centered on (cssWidth/2, cssHeight/2)
417	    // scaled by zoom — mostly *outside* our (0,0)-(cssWidth,cssHeight)
418	    // content — instead of that content filling the frame. This is the
419	    // actual cause of the "painted into a corner" symptom from the earlier
420	    // investigation (see the `dpr` field's comment): every combination tried
421	    // there still zoomed around the center, so all of them would have shown
422	    // the same wrong region regardless of scale mode or boot timing.
423	    this.cameras.main.setZoom(this.dpr).centerOn(this.cssWidth / 2, this.cssHeight / 2);
424	  }
