452	  private paint(): void {
453	    this.tweens.killAll();
454	    this.children.removeAll(true);
455	    this.staffTokens.clear();
456	    const width = Math.max(320, this.cssWidth);
457	    const height = Math.max(240, this.cssHeight);
458	    const layout = restaurantArenaLayout(width, height);
459	    const g = this.add.graphics();
460	
461	    g.fillStyle(COLORS.ink);
462	    g.fillRect(0, 0, width, height);
463	
464	    this.drawTopBar(g, layout);
465	    this.drawBrief(g, layout);
466	    this.drawKitchen(g, layout);
467	    this.drawPass(g, layout);
468	    this.drawDining(g, layout);
469	    this.drawDoor(g, layout);
470	    this.drawTickets(g, layout);
471	    this.drawFeed(g, layout);
472	    this.drawWorkers(layout);
473	    this.drawIncidentBanner(layout);
474	    this.drawOutcomeToast(layout.compact, width, height);
475	    if (!this.state.sim?.started) this.drawPreShift(layout, width, height);
476	    else if (this.state.decision) this.drawDecision(layout, width, height);
477	  }
