481	  private drawTopBar(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
482	    const bar = layout.topBar;
483	    const compact = layout.compact;
484	    const sim = this.state.sim;
485	    g.fillStyle(COLORS.panel);
486	    g.fillRoundedRect(bar.x, bar.y, bar.width, bar.height, 4);
487	
488	    const size = bar.height - (compact ? 8 : 10);
489	    const pad = compact ? 4 : 6;
490	    let x = bar.x + pad;
491	
492	    // Host-shell navigation lives on the floor too, not in chrome above it —
493	    // same reasoning as every other control here.
494	    const navWidth = size + 6;
495	    this.button(
496	      { x, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
497	      "‹",
498	      "menu",
499	      { size: compact ? 10 : 12, tip: "Back to the menu", dispatch: () => this.onUi("menu") },
500	    );
501	    x += navWidth + pad;
502	
503	    if (sim) {
504	      const paused = !sim.running;
505	      this.button(
506	        { x, y: bar.y + (bar.height - size) / 2, width: size + 6, height: size },
507	        paused ? ">" : "||",
508	        "sim_toggle",
509	        {
510	          fill: paused ? 0x3d9b6d : 0x4a3a2c,
511	          size: compact ? 10 : 12,
512	          tip: paused ? "Resume (space)" : "Pause (space)",
513	        },
514	      );
515	      x += size + 6 + pad;
516	
517	      this.button(
518	        { x, y: bar.y + (bar.height - size) / 2, width: size + 10, height: size },
519	        `×${sim.speed}`,
520	        "sim_speed",
521	        { size: compact ? 8 : 10, tip: "Speed (f)" },
522	      );
523	      x += size + 10 + pad;
524	    }
525	
526	    // Clock + a bar that fills as the shift burns down. A stopped clock has
527	    // to be unmistakable, so it greys out and says so.
528	    const paused = Boolean(sim?.started) && !sim?.running;
529	    const clock = this.add
530	      .text(x, bar.y + bar.height / 2, clockLabel(this.state.clock.minute), {
531	        color: paused ? "#8d8378" : "#fff3d6",
532	        fontFamily: MONO,
533	        fontSize: compact ? this.fs(11) : this.fs(14),
534	        fontStyle: "bold",
535	      })
536	      .setOrigin(0, 0.5);
537	    x += clock.width + pad;
538	
539	    if (paused) {
540	      const label = this.state.decision ? "NEEDS A CALL" : "PAUSED";
541	      const chip = this.add
542	        .text(x, bar.y + bar.height / 2, label, {
543	          color: "#2b2118",
544	          backgroundColor: this.state.decision ? "#f2cc5c" : "#8d8378",
545	          fontFamily: MONO,
546	          fontSize: compact ? this.fs(6) : this.fs(7),
547	          fontStyle: "bold",
548	          padding: { x: 3, y: 1 },
549	        })
550	        .setOrigin(0, 0.5);
551	      if (this.state.decision) {
552	        this.tweens.add({ targets: chip, alpha: 0.45, duration: 620, yoyo: true, repeat: -1 });
553	      }
554	      x += chip.width + pad;
555	    }
556	
557	    const { tick, maxTicks } = this.state.episode;
558	    const progress = maxTicks > 0 ? Math.min(1, Math.max(0, tick / maxTicks)) : 0;
559	
560	    // Restart sits at the hard-right edge; money and reputation sit just
561	    // inside it, and the progress bar takes whatever slack is left.
562	    const restartX = bar.x + bar.width - pad - navWidth;
563	    this.button(
564	      { x: restartX, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
565	      "↻",
566	      "restart",
567	      { size: compact ? 10 : 12, tip: "Restart the shift", dispatch: () => this.onUi("restart") },
568	    );
569	    const helpX = restartX - pad - navWidth;
570	    this.button(
571	      { x: helpX, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
572	      "?",
573	      "help",
574	      { size: compact ? 10 : 12, tip: "How to Play", dispatch: () => this.onUi("help") },
575	    );
576	    const rightEdge = helpX - pad;
577	
578	    // Takings read against tonight's target, so the number always means
579	    // something — "$96" alone tells the player nothing.
580	    const goalCash = this.state.goal?.cash;
581	    const amount = Math.round(this.state.outcomes.cash);
582	    const formattedCash = amount < 0 ? `-$${Math.abs(amount)}` : `$${amount}`;
583	    const cash = goalCash ? `${formattedCash}/$${goalCash}` : formattedCash;
584	    // A 1-5 rating reads at a glance the way a percentage never does —
585	    // "3/5" is a milestone a player recognizes instantly, not a figure they
586	    // have to interpret.
587	    const stars = Math.max(1, Math.min(5, Math.round((this.state.reputation ?? 50) / 20)));
588	    const rating = `${stars}/5`;
589	    const onTarget = !goalCash || this.state.outcomes.cash >= goalCash;
590	    const cashText = this.add
591	      .text(rightEdge, bar.y + bar.height / 2 - (compact ? 5 : 6), cash, {
592	        color: onTarget ? "#7ddc9f" : "#e8ddcc",
593	        fontFamily: MONO,
594	        fontSize: compact ? this.fs(10) : this.fs(12),
595	        fontStyle: "bold",
596	      })
597	      .setOrigin(1, 0.5);
598	    const repText = this.add
599	      .text(rightEdge, bar.y + bar.height / 2 + (compact ? 6 : 7), `${rating}   ${this.state.outcomes.completed} served`, {
600	        color: "#f2cc5c",
601	        fontFamily: MONO,
602	        fontSize: compact ? this.fs(7) : this.fs(9),
603	      })
604	      .setOrigin(1, 0.5);
605	
606	    const trackX = x + pad;
607	    const trackWidth = Math.max(16, rightEdge - Math.max(cashText.width, repText.width) - pad - trackX);
608	    const trackHeight = compact ? 4 : 6;
609	    const trackY = bar.y + (bar.height - trackHeight) / 2;
610	    g.fillStyle(0x4a3a2c);
611	    g.fillRoundedRect(trackX, trackY, trackWidth, trackHeight, trackHeight / 2);
612	    if (progress > 0) {
613	      g.fillStyle(COLORS.pass);
614	      g.fillRoundedRect(trackX, trackY, Math.max(trackHeight, trackWidth * progress), trackHeight, trackHeight / 2);
615	    }
616	  }
