639	  private drawKitchen(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
640	    const zone = layout.kitchen;
641	    const compact = layout.compact;
642	    this.zonePanel(g, zone, COLORS.kitchen, "KITCHEN", compact);
643	
644	    const pad = compact ? 5 : 8;
645	    const top = zone.y + (compact ? 15 : 20);
646	    const oven = this.state.equipment.find((item) => item.kind === "oven");
647	    const stock = Object.values(this.state.inventory).reduce((sum, count) => sum + count, 0);
648	    const stations: Array<{ label: string; sub: string; color: number; action?: string; tip?: string; dim?: boolean }> = [
649	      { label: "PREP", sub: "", color: 0xf1e6c8 },
650	      { label: "PANTRY", sub: `${stock} left`, color: 0xd4b483 },
651	      {
652	        label: "OVEN",
653	        sub: oven?.status === "failed" ? "DEAD — CLICK" : oven?.status === "degraded" ? "limping" : "ready",
654	        color: oven?.status === "failed" ? COLORS.failed : oven?.status === "degraded" ? 0xd6892f : COLORS.working,
655	        action: oven?.status === "failed" ? "inspect_oven" : undefined,
656	        tip: oven?.status === "failed" ? "Fix the oven" : undefined,
657	      },
658	    ];
659	    // The one in-shift purchase on offer — a permanent second pair of hands
660	    // at the stations, paid for out of tonight's own takings. Affordable
661	    // once cash clears the cost; a one-time click, not a recurring cost.
662	    const upgrade = this.state.upgrade;
663	    if (upgrade) {
664	      const affordable = this.state.outcomes.cash >= upgrade.cost;
665	      stations.push(
666	        upgrade.bought
667	          ? { label: upgrade.label.toUpperCase(), sub: "installed", color: 0x8fbfa0 }
668	          : {
669	              label: `+${upgrade.label.toUpperCase()}`,
670	              sub: `$${upgrade.cost} — click`,
671	              color: affordable ? COLORS.pass : 0x5c4a3a,
672	              action: affordable ? "buy_second_stove" : undefined,
673	              tip: affordable ? "Second pair of hands, all shift" : `Need $${upgrade.cost} to install`,
674	              dim: !affordable,
675	            },
676	      );
677	    }
678	
679	    // On a real desktop window this zone can run far taller than these
680	    // cards need — capped height plus vertical centering keeps them a
681	    // sensible size instead of stretching into empty slabs.
682	    const rawStationHeight = (zone.height - (top - zone.y) - pad * (stations.length + 1)) / stations.length;
683	    const stationHeight = Math.min(compact ? 40 : 76, Math.max(14, rawStationHeight));
684	    const groupHeight = stationHeight * stations.length + pad * (stations.length - 1);
685	    const groupTop = top + Math.max(0, (zone.height - (top - zone.y) - groupHeight) / 2);
686	
687	    stations.forEach((station, index) => {
688	      const y = groupTop + index * (stationHeight + pad);
689	      const rect = { x: zone.x + pad, y, width: zone.width - pad * 2, height: stationHeight };
690	      g.fillStyle(station.color, station.dim ? 0.6 : 1);
691	      g.fillRoundedRect(rect.x, rect.y, rect.width, rect.height, 3);
692	      g.lineStyle(1, COLORS.kitchenDark, 0.8);
693	      g.strokeRoundedRect(rect.x, rect.y, rect.width, rect.height, 3);
694	      const broken = station.label === "OVEN" && oven?.status === "failed";
695	      this.add
696	        .text(zone.x + zone.width / 2, y + stationHeight / 2 - (station.sub ? 4 : 0), station.label, {
697	          color: broken ? "#ffffff" : "#2b2118",
698	          fontFamily: MONO,
699	          fontSize: compact ? this.fs(6) : this.fs(8),
700	          fontStyle: "bold",
701	        })
702	        .setOrigin(0.5);
703	      if (station.sub) {
704	        this.add
705	          .text(zone.x + zone.width / 2, y + stationHeight / 2 + 5, station.sub, {
706	            color: broken ? "#ffe2e2" : "#5c4a3a",
707	            fontFamily: MONO,
708	            fontSize: compact ? this.fs(5) : this.fs(6),
709	            fontStyle: "bold",
710	          })
711	          .setOrigin(0.5);
712	      }
713	      if (station.action) this.hotspot(rect, station.action, station.tip);
714	    });
715	  }
