717	  private drawPass(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
718	    const zone = layout.pass;
719	    this.zonePanel(g, zone, COLORS.pass, "PASS", layout.compact, true);
720	    this.hotspot(zone, "verify_substitution", "Verify the ticket");
721	    const y = zone.y + zone.height * 0.6;
722	    g.fillStyle(0x7b4c2e);
723	    g.fillRoundedRect(zone.x + 3, y, zone.width - 6, layout.compact ? 12 : 18, 3);
724	    // Plates waiting on the pass = orders cooked but not yet run to a table.
725	    const ready = this.state.orders.filter((order) => order.status === "ready").length;
726	    for (let i = 0; i < Math.min(3, ready); i++) {
727	      g.fillStyle(0xfff3d6);
728	      g.fillCircle(zone.x + zone.width / 2, y + 4 + i * (layout.compact ? 5 : 7), layout.compact ? 2.5 : 3.5);
729	    }
730	    if (ready > 0) {
731	      this.add
732	        .text(zone.x + zone.width / 2, zone.y + zone.height - 4, `${ready}`, {
733	          color: "#2b2118",
734	          fontFamily: MONO,
735	          fontSize: layout.compact ? this.fs(7) : this.fs(9),
736	          fontStyle: "bold",
737	        })
738	        .setOrigin(0.5, 1);
739	    }
740	  }
