1014	   * The service log. Watching the staff think is what makes their behaviour
1015	   * legible — and a legible floor is what makes the player's calls informed.
1016	   */
1017	  private drawFeed(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
1018	    const zone = layout.feed;
1019	    const compact = layout.compact;
1020	    g.fillStyle(COLORS.panel);
1021	    g.fillRoundedRect(zone.x, zone.y, zone.width, zone.height, 4);
1022	    this.add.text(zone.x + 6, zone.y + 4, "EVENT FEED", {
1023	      color: "#f2cc5c",
1024	      fontFamily: "Arial Narrow, sans-serif",
1025	      fontSize: compact ? this.fs(7) : this.fs(9),
1026	      fontStyle: "bold",
1027	    });
1028	
1029	    // Keep the narrative spine visible while the activity log scrolls past it.
1030	    // This is deliberately fixed-order UI, not inferred from whichever feed
1031	    // entries happen to be in the tail of a long shift.
1032	    const milestoneTop = zone.y + (compact ? 14 : 18);
1033	    const milestone = this.add.text(zone.x + 6, milestoneTop, milestoneFeedText(), {
1034	      color: "#c9bdae",
1035	      fontFamily: MONO,
1036	      fontSize: compact ? this.fs(5) : this.fs(6),
1037	      fontStyle: "bold",
1038	      wordWrap: { width: zone.width - 12 },
1039	      maxLines: layout.feedBeside ? 2 : 1,
1040	      lineSpacing: compact ? 1 : 2,
1041	    });
1042	    void milestone;
1043	
1044	    const entries = this.state.feed ?? [];
1045	    const top = milestoneTop + milestone.height + (compact ? 2 : 4);
1046	    // The side rail is narrow but tall, so entries there get a second line
1047	    // rather than being cut off mid-sentence.
1048	    const bodyLines = layout.feedBeside ? 2 : 1;
1049	    const lineHeight = (compact ? 15 : 18) + (bodyLines - 1) * (compact ? 7 : 9);
1050	    const rows = Math.max(1, Math.floor((zone.height - (top - zone.y) - 2) / lineHeight));
1051	    const shown = entries.slice(-rows);
1052	
1053	    if (shown.length === 0) {
1054	      this.add.text(zone.x + 6, top + 2, "Press Play to open.", {
1055	        color: "#8d8378",
1056	        fontFamily: MONO,
1057	        fontSize: compact ? this.fs(7) : this.fs(9),
1058	      });
1059	      return;
1060	    }
1061	
1062	    shown.forEach((entry, index) => {
1063	      const y = top + index * lineHeight;
1064	      const color = VOICE_COLORS[entry.voice] ?? "#c9bdae";
1065	      // The player's own calls get a left accent rule and full-strength body
1066	      // text, so "what I decided" separates from "what the staff said" at a
1067	      // glance rather than only by reading the name (#304). The feed is the
1068	      // record of the shift; a manager scanning it back should be able to
1069	      // find their own decisions without parsing every line.
1070	      const mine = entry.voice === "you";
1071	      const textX = zone.x + 6 + (mine ? 4 : 0);
1072	      if (mine) {
1073	        g.fillStyle(0x7ddc9f);
1074	        g.fillRoundedRect(zone.x + 3, y, 2, lineHeight - (compact ? 3 : 4), 1);
1075	      }
1076	      const head = this.add.text(textX, y, `${entry.clock} ${entry.who}`, {
1077	        color,
1078	        fontFamily: MONO,
1079	        fontSize: compact ? this.fs(6) : this.fs(7),
1080	        fontStyle: "bold",
1081	      });
1082	      this.add.text(textX, y + (compact ? 7 : 8), entry.text, {
1083	        color: entry.kind === "thought" ? "#9a8f82" : mine ? "#fff3d6" : "#e8ddcc",
1084	        fontFamily: MONO,
1085	        fontSize: compact ? this.fs(6) : this.fs(8),
1086	        fontStyle: entry.kind === "thought" ? "italic" : "normal",
1087	        wordWrap: { width: zone.width - 12 - (mine ? 4 : 0) },
1088	        maxLines: bodyLines,
1089	      });
1090	      void head;
1091	    });
