1135	  /**
1136	   * The service log tells the same story in a rail nobody has to be
1137	   * looking at — a bubble over the actual person doing the thinking is
1138	   * what makes the floor read as staffed by someone, not just occupied.
1139	   */
1140	  private latestLineFor(role: Role): string | undefined {
1141	    const feed = this.state.feed;
1142	    if (!feed || feed.length === 0) return undefined;
1143	    for (let i = feed.length - 1; i >= Math.max(0, feed.length - 6); i--) {
1144	      const entry = feed[i]!;
1145	      if (entry.voice === role && (entry.kind === "thought" || entry.kind === "action")) return entry.text;
1146	    }
1147	    return undefined;
1148	  }
