1150	  private drawSpeechBubble(token: Phaser.GameObjects.Container, role: Role, compact: boolean): void {
1151	    const line = this.latestLineFor(role);
1152	    if (!line) return;
1153	    const trimmed = line.length > 46 ? `${line.slice(0, 44)}…` : line;
1154	    const fontSize = compact ? "6px" : "7px";
1155	    const label = this.add.text(0, 0, trimmed, {
1156	      color: "#2b2118",
1157	      fontFamily: MONO,
1158	      fontSize,
1159	      wordWrap: { width: compact ? 100 : 130 },
1160	      maxLines: 2,
1161	      align: "center",
1162	    });
1163	    const padX = 5;
1164	    const padY = 4;
1165	    const w = label.width + padX * 2;
1166	    const h = label.height + padY * 2;
1167	    const localX = Math.min(Math.max(-w / 2, 4 - token.x), this.cssWidth - w - 4 - token.x);
1168	    const bubbleY = -(compact ? 20 : 26) - h;
1169	    const bg = this.add.rectangle(0, 0, w, h, 0xfff3d6, 0.96).setOrigin(0, 0);
1170	    bg.setStrokeStyle(1, ROLE_COLORS[role], 0.9);
1171	    label.setPosition(padX, padY);
1172	    const tail = this.add.triangle(w / 2 - localX, h + 4, -4, 0, 4, 0, 0, 5, 0xfff3d6).setOrigin(0.5, 0);
1173	    const bubble = this.add.container(localX, bubbleY, [bg, label, tail]);
1174	    bubble.setAlpha(0.97);
1175	    token.add(bubble);
1176	  }
