1367	   * Every `paint()` redraws this from scratch like everything else, so the
1368	   * fade can't be a single tween that outlives one repaint — instead this
1369	   * recomputes the correct in-flight alpha from elapsed wall-clock time on
1370	   * every call (right even if a tick landed mid-fade) and hands off to one
1371	   * tween per paint for the remaining motion.
1372	   */
1373	  private drawOutcomeToast(compact: boolean, width: number, height: number): void {
1374	    const toast = this.outcomeToast;
1375	    if (!toast) return;
1376	    const elapsed = Date.now() - toast.startedAt;
1377	    if (elapsed >= this.outcomeToastMs) {
1378	      this.outcomeToast = undefined;
1379	      return;
1380	    }
1381	    const tone = toast.tone === "safe" ? 0x2f5c46 : toast.tone === "risky" ? 0x6b2f2b : 0x40342a;
1382	
1383	    const label = this.add.text(0, 0, toast.headline, {
1384	      color: "#fff3d6",
1385	      fontFamily: MONO,
1386	      fontSize: compact ? this.fs(8) : this.fs(10),
1387	      fontStyle: "bold",
1388	    });
1389	    const padX = compact ? 10 : 14;
1390	    const padY = compact ? 6 : 8;
1391	    const boxWidth = label.width + padX * 2;
1392	    const boxHeight = label.height + padY * 2;
1393	    const x = (width - boxWidth) / 2;
1394	    const y = height * 0.34 - boxHeight / 2;
1395	
1396	    const bg = this.add.rectangle(0, 0, boxWidth, boxHeight, tone).setOrigin(0, 0);
1397	    bg.setStrokeStyle(2, COLORS.pass, 0.9);
1398	    label.setPosition(padX, padY);
1399	    const toastBox = this.add.container(x, y, [bg, label]).setDepth(45);
1400	
1401	    const fadeInMs = 180;
1402	    if (elapsed < fadeInMs) {
1403	      toastBox.setAlpha(elapsed / fadeInMs);
1404	      this.tweens.add({ targets: toastBox, alpha: 1, duration: fadeInMs - elapsed });
1405	    }
1406	    const remaining = this.outcomeToastMs - elapsed;
1407	    const fadeOutMs = Math.min(400, remaining);
1408	    this.tweens.add({ targets: toastBox, alpha: 0, delay: Math.max(0, remaining - fadeOutMs), duration: fadeOutMs });
1409	  }
