1650	
1651	    g.fillStyle(COLORS.panel);
1652	    g.fillRoundedRect(zone.x, zone.y, zone.width, zone.height, 4);
1653	
1654	    const pad = compact ? 5 : 7;
1655	    const rowOne = zone.y + (compact ? 3 : 4);
1656	
1657	    // Row one: the tally, right-aligned, with the receipt for the last call
1658	    // sitting quietly on the left of it.
1659	    const chipColors: Record<"ok" | "warn" | "bad", { bg: string; fg: string }> = {
1660	      ok: { bg: "#3a2e24", fg: "#a99b8a" },
1661	      warn: { bg: "#6b5124", fg: "#f7e2b4" },
1662	      bad: { bg: "#7a2b26", fg: "#ffdcd6" },
1663	    };
1664	    let chipRight = zone.x + zone.width - pad;
1665	    for (const chip of [...brief.chips].reverse()) {
1666	      const colors = chipColors[chip.tone];
1667	      const text = this.add
1668	        .text(chipRight, rowOne, `${chip.label} ${chip.value}`, {
1669	          color: colors.fg,
1670	          backgroundColor: colors.bg,
1671	          fontFamily: MONO,
1672	          fontSize: compact ? this.fs(6) : this.fs(7),
1673	          fontStyle: "bold",
