/**
 * Where every part of the Restaurant Arena floor goes, for a given canvas.
 *
 * This is the whole geometry of the scene in one pure function: no Phaser, no
 * state, no side effects — feed it a width and a height and it hands back the
 * rects. Pulling it out of the scene is what makes the responsive behaviour
 * testable at all; the scene itself can only be checked by looking at it.
 *
 * Two things it decides that the scene cannot decide for itself:
 *
 * - `scale`. The floor was authored for a 520×740 window (`BASELINE_WIDTH` /
 *   `BASELINE_HEIGHT`), where a 6px label is fine. Blown up to a 1600px
 *   desktop window that same 6px label is a smudge — the room grows and the
 *   type does not, which is the "unreadable on a big screen" failure. So the
 *   layout reports one multiplier that the scene applies to every font size
 *   and every text-metric offset. It follows the *smaller* of the two axis
 *   ratios, because growing type off the ratio of a very wide, very short
 *   window would push the tall bands (the ticket rail, the log) off the
 *   bottom.
 *
 * - `compact`. Under roughly `COMPACT_WIDTH` × `COMPACT_HEIGHT` there is no
 *   slack left to spend: labels get their tight sizes and nothing grows.
 *   `scale` is pinned to 1 there, so the two never fight.
 *
 * Everything returned is guaranteed to sit inside `width` × `height`: the
 * vertical bands are allocated out of a budget that is shrunk to fit before
 * any of them is placed (see `shrink` below), and the floor takes whatever is
 * left rather than being sized independently and hoping.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The window the floor was drawn for. `scale` is exactly 1 here. */
export const BASELINE_WIDTH = 520;
export const BASELINE_HEIGHT = 740;

/**
 * Past roughly twice the baseline the room is big enough that further growth
 * only wastes the space labels could be spending on more of the floor, so the
 * multiplier stops here.
 */
export const MAX_SCALE = 1.9;

/** Below either of these the layout is compact and type stops growing. */
export const COMPACT_WIDTH = 460;
export const COMPACT_HEIGHT = 420;

/**
 * The service log moves from a band under the floor to a rail beside it once
 * the window can spare the width — below this it would squeeze the dining
 * room down to a corridor.
 */
export const FEED_BESIDE_WIDTH = 600;

/**
 * The host stand is a click target with two lines of type on it, so it has a
 * floor it never goes under however small the window gets — a 30×12 stand is
 * neither readable nor hittable.
 */
export const MIN_STAND_WIDTH = 56;
export const MIN_STAND_HEIGHT = 22;

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(1, Math.round(width));
  const h = Math.max(1, Math.round(height));

  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
  const fit = Math.min(w / BASELINE_WIDTH, h / BASELINE_HEIGHT);
  // Never below 1: the baseline sizes are already the small ones, and a
  // compact window is handled by `compact`, not by shrinking type further.
  const scale = compact ? 1 : clamp(fit, 1, MAX_SCALE);
  const feedBeside = w >= FEED_BESIDE_WIDTH;

  /** A baseline-authored length at this window's scale. */
  const px = (base: number) => Math.round(base * scale);

  // ── Vertical bands ───────────────────────────────────────────────────
  // Ideal heights first, then one shrink pass so the whole stack provably
  // fits before anything is positioned.
  let margin = Math.max(3, px(compact ? 6 : 8));
  let gap = Math.max(2, px(compact ? 4 : 6));
  let topBarHeight = px(compact ? 32 : 38);
  let briefHeight = px(compact ? 26 : 32);
  let ticketsHeight = px(compact ? 56 : 72);
  let feedHeight = feedBeside ? 0 : Math.max(px(compact ? 80 : 110), Math.round(h * 0.2));
  // margin, topBar, gap, brief, gap, floor, gap, tickets, [gap, feed,] margin
  const gaps = feedBeside ? 3 : 4;
  const chrome = () =>
    margin * 2 + topBarHeight + briefHeight + ticketsHeight + feedHeight + gap * gaps;

  // The floor is the game; the bands around it are what give way. Capped at a
  // share of the window so the reservation itself can never exceed it.
  const minFloor = Math.min(px(compact ? 90 : 120), Math.round(h * 0.3));
  const ideal = chrome();
  if (ideal > h - minFloor) {
    const shrink = Math.max(0, (h - minFloor) / ideal);
    // Floor(), never round(), and no lower clamps: every band only ever gets
    // smaller here, which is what keeps the sum inside `h`.
    margin = Math.floor(margin * shrink);
    gap = Math.floor(gap * shrink);
    topBarHeight = Math.floor(topBarHeight * shrink);
    briefHeight = Math.floor(briefHeight * shrink);
    ticketsHeight = Math.floor(ticketsHeight * shrink);
    feedHeight = Math.floor(feedHeight * shrink);
  }
  const floorHeight = h - chrome();

  const briefY = margin + topBarHeight + gap;
  const bodyY = briefY + briefHeight + gap;

  // ── Horizontal split ─────────────────────────────────────────────────
  const bodyX = margin;
  const bodyWidth = Math.max(1, w - margin * 2);
  const feedWidth = feedBeside
    ? Math.min(Math.round(bodyWidth * 0.4), Math.max(px(180), Math.round(bodyWidth * 0.28)))
    : bodyWidth;
  const floorWidth = Math.max(1, feedBeside ? bodyWidth - gap - feedWidth : bodyWidth);

  const kitchenWidth = Math.round(floorWidth * 0.25);
  // The pass is a slot, not a room, but it carries a rotated label and a
  // plate stack — it has a floor width, and a ceiling so it cannot eat the
  // dining room on a narrow window.
  const passWidth = clamp(
    Math.round(floorWidth * 0.07),
    Math.min(px(compact ? 20 : 24), Math.round(floorWidth * 0.14)),
    Math.round(floorWidth * 0.14),
  );
  const diningX = bodyX + kitchenWidth + gap + passWidth + gap;
  const diningWidth = Math.max(1, bodyX + floorWidth - diningX);

  // The door sits under the dining room, tall enough to hold the host stand
  // plus its zone label whatever the window does.
  const labelH = Math.max(8, px(compact ? 11 : 14));
  const standPad = Math.max(2, px(4));
  const standIdealHeight = Math.max(MIN_STAND_HEIGHT, px(compact ? 26 : 34));
  const doorMin = labelH + standIdealHeight + standPad;
  const doorHeight = Math.min(
    Math.max(Math.round(floorHeight * 0.32), doorMin),
    Math.max(doorMin, floorHeight - gap - Math.round(floorHeight * 0.3)),
  );
  const diningHeight = Math.max(1, floorHeight - doorHeight - gap);

  const kitchen = { x: bodyX, y: bodyY, width: kitchenWidth, height: floorHeight };
  const pass = { x: bodyX + kitchenWidth + gap, y: bodyY, width: passWidth, height: floorHeight };
  const dining = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
  const door = { x: diningX, y: bodyY + diningHeight + gap, width: diningWidth, height: doorHeight };

  // Left gutter so the waiting parties still have somewhere to queue beside
  // the stand rather than on top of it.
  const hostGutter = Math.max(10, px(compact ? 28 : 40));
  const standWidth = Math.max(
    MIN_STAND_WIDTH,
    Math.min(px(90), door.width - hostGutter - standPad),
  );
  const standHeight = Math.max(
    MIN_STAND_HEIGHT,
    Math.min(standIdealHeight, door.height - labelH - standPad),
  );
  const doorStand = {
    x: Math.round(Math.min(door.x + hostGutter, door.x + Math.max(0, door.width - standWidth))),
    y: Math.round(door.y + Math.min(labelH, Math.max(0, door.height - standHeight))),
    width: standWidth,
    height: standHeight,
  };

  // The hallway: one line through the middle of the pass, which is also the
  // middle of the kitchen and the lower half of the dining room. Staff ride
  // it between stations instead of cutting the corner through a table.
  const spineY = Math.round(pass.y + pass.height / 2);

  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: { x: Math.round(kitchen.x + kitchen.width / 2), y: spineY },
    pass: { x: Math.round(pass.x + pass.width / 2), y: spineY },
    floor: { x: Math.round(dining.x + dining.width / 2), y: Math.round(dining.y + dining.height / 2) },
    queue: {
      x: Math.round(doorStand.x + doorStand.width / 2),
      y: Math.round(doorStand.y + doorStand.height / 2),
    },
  };

  return {
    compact,
    scale,
    feedBeside,
    topBar: { x: bodyX, y: margin, width: bodyWidth, height: topBarHeight },
    brief: { x: bodyX, y: briefY, width: bodyWidth, height: briefHeight },
    kitchen,
    pass,
    dining,
    door,
    doorStand,
    waypoints,
    spineY,
    tickets: { x: bodyX, y: bodyY + floorHeight + gap, width: floorWidth, height: ticketsHeight },
    feed: feedBeside
      ? {
          x: bodyX + floorWidth + gap,
          y: bodyY,
          width: feedWidth,
          height: floorHeight + gap + ticketsHeight,
        }
      : { x: bodyX, y: h - margin - feedHeight, width: bodyWidth, height: feedHeight },
  };
}

