/**
 * Staff movement across the Restaurant Arena floor.
 *
 * Two ideas, and everything here follows from them.
 *
 * **The floor is a hallway, not a graph of teleports.** Kitchen, pass, dining
 * floor and door queue sit in that order along one line, and `WALK_GRAPH`
 * wires them that way: the pass and the floor are through-stations, so a chef
 * sent from the kitchen to the door *walks past the pass and across the
 * dining room* rather than appearing at the door. That is the whole point of
 * animating this at all — the player can see the cost of the assignment they
 * just made, because the person is out of position for as long as the walk
 * takes.
 *
 * **A walk rides the hallway.** `corridorPoints` never emits a diagonal: it
 * steps onto the hallway line (`spineY`, from the layout), travels along it,
 * and steps off at the far end. A straight line from the kitchen to the door
 * would cut through the middle of the dining room and read as a person
 * walking over the tables.
 *
 * `StaffWalker` owns one person's pixels. It is deliberately free of Phaser:
 * the scene creates a container wherever the walker says it is, and the
 * walker knows nothing about it. That keeps the movement — the part with the
 * arithmetic in it — testable, and it means a repaint (which destroys every
 * game object in the scene) can't lose a walk in progress.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * The floor as one hallway: kitchen ── pass ── floor ── queue. Neighbours
 * only; nothing skips a station, which is what makes `bfsPath("kitchen",
 * "queue")` route through both middles.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** A walking pace, not a teleport and not a shuffle. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Below this a hop is treated as "already there" rather than divided by. */
const MIN_HOP_MS = 1;

/** Snapping tolerance in pixels — layout rounding, not real distance. */
const EPSILON = 0.5;

/**
 * Shortest station-to-station route, inclusive of both ends. `from === to`
 * yields the single node.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];

  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node]) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let cursor: WalkNode = to;
        while (cursor !== from) {
          cursor = previous.get(cursor)!;
          path.unshift(cursor);
        }
        return path;
      }
      queue.push(next);
    }
  }
  return [];
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Every segment is axis-aligned, and any segment that moves horizontally does
 * so *on* the hallway line. `start` itself is not repeated in the result — it
 * is where the walker already is.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let cursor: Point = { x: start.x, y: start.y };

  const push = (point: Point) => {
    if (Math.abs(point.x - cursor.x) < EPSILON && Math.abs(point.y - cursor.y) < EPSILON) return;
    points.push(point);
    cursor = point;
  };

  for (const node of nodes) {
    const target = waypoints[node];
    if (!target) continue;
    if (Math.abs(target.x - cursor.x) < EPSILON) {
      // Same column already — walking out to the hallway and back would be a
      // detour, not a route.
      push({ x: cursor.x, y: target.y });
      continue;
    }
    if (Math.abs(cursor.y - spineY) >= EPSILON) push({ x: cursor.x, y: spineY });
