/**
 * Holds a repaint back while the player is dragging a staff token.
 *
 * The arena scene has exactly one drawing strategy: `paint()` destroys every
 * game object and builds the whole floor again. That is fine for a state tick
 * and fatal for a drag — the token under the pointer is one of the objects
 * that gets destroyed, so a tick landing mid-drag deletes the thing the player
 * is holding and rebuilds it back in its old station. The drag looks like it
 * snapped back and the drop lands on nothing.
 *
 * So a drag closes the gate. Anything that wanted to repaint while it was
 * closed is remembered as *one* owed repaint — no matter how many ticks went
 * by, since a repaint always draws the current state and replaying five of
 * them would draw the same frame five times — and `endDrag()` tells the caller
 * to run it once the token has landed.
 *
 * `resize()` is the other way a drag can end: the scene is torn down and
 * rebooted at the new size (see `mountRestaurantArenaScene`), which repaints
 * from scratch by construction. So a resize drops the open drag *and* forgets
 * anything owed — otherwise the stray `dragend` that arrives after the pointer
 * is released over a dead canvas would claim a repaint the fresh scene has
 * already done.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    // Deliberately does not clear `owed`: the only ways it can still be set
    // here are a drag that never ended, and losing that paint is worse than
    // replaying one.
    this.dragging = true;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case
   * the paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (this.dragging) {
      this.owed = true;
      return false;
    }
    return true;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it
   * (and thus needs to be replayed by the caller now).
   */
  endDrag(): boolean {
    const owed = this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

