  this.shownOutcomeId = toastState.shownOutcomeId;
  this.outcomeToast = toastState.outcomeToast;
  if (!this.sys.isActive()) return;
  this.requestPaint();
}

/**
 * The only way anything other than a drag ends up repainting. A repaint
 * destroys every game object, including the token under the player's
 * finger, so while a drag is open the gate holds the paint and hands it back
 * on drop — see `RepaintGate` for why exactly one is replayed.
 */
private requestPaint(): void {
  if (this.repaintGate.requestPaint()) this.paint();
}

/**
 * The window changed size. The scene is about to be torn down and rebooted
 * (see `mountRestaurantArenaScene`), which repaints from scratch, so any
 * open drag is abandoned and nothing is owed — the `dragend` that arrives
 * after the pointer comes up over the old canvas must not claim a repaint
 * the fresh scene has already done.
 */
noteResize(): void {
  this.repaintGate.resize();
  this.clearDropHints();
  for (const walker of this.walkers.values()) walker.dragging = false;
}

/**
 * Move the staff along. Phaser's own loop, at `state.sim.speed` so a walk
 * takes as long in game time at 4× as it does at 1× — and freezes with the
 * clock, since a paused shift with people still crossing the floor reads as
 * the pause not having taken.
 */
update(_time: number, delta: number): void {
  if (this.walkers.size === 0) return;
  const speed = this.running ? Math.max(0, this.state.sim?.speed ?? 1) : 0;
  let arrived = false;
  for (const [role, walker] of this.walkers) {
    const wasWalking = walker.walking;
    const moved = walker.step(delta, speed);
    if (moved) this.placeToken(role, walker);
    // Arriving settles the token into its idle bob, which only a repaint
    // sets up — and it re-reads the layout, so it also fixes up anyone whose
    // slot moved while they were walking.
    if (wasWalking && !walker.walking) arrived = true;
  }
  if (arrived) this.requestPaint();
}

private placeToken(role: Role, walker: StaffWalker): void {
  const token = this.staffTokens.get(role);
