/**
 * The waypoint set one particular worker walks against: the shared station
 * centres, except for their own destination, which is the slot they will
 * stand in once two people share a station.
 */
private slotWaypoints(location: Location, slot: ArenaPoint, layout: RestaurantArenaLayout): Record<Location, ArenaPoint> {
  return { ...layout.waypoints, [location]: slot };
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();
  const live = new Set<Role>();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    live.add(worker.role);

    // The walker is the source of truth for where this person *is*; the
    // state only says where they have been sent. A reassignment starts a
    // walk down the hallway, so the player can see the gap it opens.
    let walker = this.walkers.get(worker.role);
    if (!walker) {
      walker = new StaffWalker(location, slot);
      this.walkers.set(worker.role, walker);
    } else if (!walker.dragging) {
      walker.setTarget(location, this.slotWaypoints(location, slot, layout), layout.spineY);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
    figure?.setScale(walker.facing, 1);
    this.staffTokens.set(worker.role, token);
    this.makeDraggable(token, worker.role, walker, layout);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
  }

  for (const role of [...this.walkers.keys()]) {
    if (!live.has(role)) this.walkers.delete(role);
  }
}

// ── Dragging staff between stations ──────────────────────────────────

/** The four droppable zones, in the order a point is tested against them. */
private dropZones(layout: RestaurantArenaLayout): { location: Location; rect: ArenaRect }[] {
  return [
    { location: "queue", rect: layout.door },
    { location: "kitchen", rect: layout.kitchen },
    { location: "pass", rect: layout.pass },
    { location: "floor", rect: layout.dining },
  ];
}

private zoneAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  for (const { location, rect } of this.dropZones(layout)) {
    if (x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height) {
      return location;
    }
  }
  return undefined;
}

/**
 * Pick a worker up and drop them on a zone to reassign them — the same
 * `assign_<role>_<location>` move the staff take themselves, so it replays
 * like any other action.
 *
 * The drag holds back repaints for its whole duration (`RepaintGate`):
 * otherwise the tick that lands while the player is halfway across the floor
 * destroys the token in their hand and rebuilds it back in its old station,
 * which reads as the drag being rejected. The held repaint runs on drop,
 * after the assignment has been dispatched, so the floor catches up in one
 * frame with the worker already in their new zone.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  walker: StaffWalker,
  layout: RestaurantArenaLayout,
): void {
  const grabWidth = this.s(30);
  const grabHeight = this.s(40);
  token.setSize(grabWidth, grabHeight);
  token.setInteractive({ draggable: true, useHandCursor: true });

  token.on("dragstart", () => {
    this.repaintGate.beginDrag();
    walker.dragging = true;
    this.tweens.killTweensOf(token);
    token.setDepth(80);
    this.showDropHints(layout, walker.node);
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    walker.x = dragX;
    walker.y = dragY;
    token.setPosition(dragX, dragY);
    this.highlightDropHint(this.zoneAt(dragX, dragY, layout));
  });

  token.on("dragend", () => {
    walker.dragging = false;
    this.clearDropHints();
    const dropped = this.zoneAt(walker.x, walker.y, layout);
    const from = walker.node;
    if (dropped && dropped !== from) {
      // Land the token first so the reassignment never shows the person in
      // two places, then dispatch — the action's own repaint is held by the
      // still-open gate and replayed by `endDrag()` below.
      walker.snap(layout.waypoints[dropped], dropped);
      this.onAction(`assign_${role}_${dropped}`);
    } else {
      walker.snap(layout.waypoints[from], from);
    }
    token.setDepth(20);
    this.placeToken(role, walker);
    if (this.repaintGate.endDrag()) this.paint();
    else this.startIdleBob(token, walker.y, role);
  });
}

/** While a token is in the air, say where it can go. */
private showDropHints(layout: RestaurantArenaLayout, from: Location): void {
  this.clearDropHints();
  for (const { location, rect } of this.dropZones(layout)) {
    const hint = this.add.rectangle(rect.x, rect.y, rect.width, rect.height).setOrigin(0, 0);
    hint.setStrokeStyle(2, location === from ? COLORS.muted : COLORS.pass, 0.7);
    hint.setDepth(70);
    hint.setName(location);
    this.dropHints.push(hint);
  }
}

private highlightDropHint(over?: Location): void {
  for (const hint of this.dropHints) {
    const active = hint.name === over;
    hint.setFillStyle(COLORS.pass, active ? 0.14 : 0);
    hint.setAlpha(active ? 1 : 0.7);
  }
}

private clearDropHints(): void {
  for (const hint of this.dropHints) hint.destroy();
  this.dropHints = [];
}

