    let chipRight = zone.x + zone.width - pad;
    for (const chip of [...brief.chips].reverse()) {
      const colors = chipColors[chip.tone];
      const text = this.add
        .text(chipRight, rowOne, `${chip.label} ${chip.value}`, {
          color: colors.fg,
          backgroundColor: colors.bg,
