import { describe, expect, test } from "bun:test";
import {
  restaurantArenaLayout,
  BASELINE_HEIGHT,
  BASELINE_WIDTH,
  COMPACT_HEIGHT,
  COMPACT_WIDTH,
  FEED_BESIDE_WIDTH,
  MAX_SCALE,
  MIN_STAND_HEIGHT,
  MIN_STAND_WIDTH,
  type ArenaRect,
  type RestaurantArenaLayout,
} from "./restaurant-arena-layout.js";

const SIZES: [number, number][] = [
  [320, 240],
  [360, 300],
  [420, 700],
  [459, 419],
  [460, 420],
  [520, 740],
  [600, 420],
  [800, 600],
  [1024, 768],
  [1440, 900],
  [1920, 1080],
  [2560, 1440],
  [1200, 300],
  [300, 900],
];

function rects(layout: RestaurantArenaLayout): [string, ArenaRect][] {
  return [
    ["topBar", layout.topBar],
    ["brief", layout.brief],
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["dining", layout.dining],
    ["door", layout.door],
    ["doorStand", layout.doorStand],
    ["tickets", layout.tickets],
    ["feed", layout.feed],
  ];
}

describe("Restaurant Arena layout", () => {
  test("scale is exactly 1 at the baseline window", () => {
    const layout = restaurantArenaLayout(BASELINE_WIDTH, BASELINE_HEIGHT);
    expect(layout.scale).toBe(1);
    expect(layout.compact).toBe(false);
  });

  test("scale follows the smaller axis ratio and caps near 1.9", () => {
    // Twice as tall as the baseline but only 1.2x as wide: the width is what
    // the type can afford to grow by.
    const narrow = restaurantArenaLayout(BASELINE_WIDTH * 1.2, BASELINE_HEIGHT * 2);
    expect(narrow.scale).toBeCloseTo(1.2, 5);

    const huge = restaurantArenaLayout(4000, 4000);
    expect(huge.scale).toBe(MAX_SCALE);
    expect(huge.scale).toBeLessThanOrEqual(1.9);
  });

  test("never scales below 1, so the baseline sizes are the floor", () => {
    for (const [w, h] of SIZES) {
      expect(restaurantArenaLayout(w, h).scale).toBeGreaterThanOrEqual(1);
    }
  });

  test("stays compact and stops growing text under the compact thresholds", () => {
    expect(restaurantArenaLayout(COMPACT_WIDTH - 1, 900).compact).toBe(true);
    expect(restaurantArenaLayout(900, COMPACT_HEIGHT - 1).compact).toBe(true);
    expect(restaurantArenaLayout(COMPACT_WIDTH, COMPACT_HEIGHT).compact).toBe(false);
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      if (layout.compact) expect(layout.scale).toBe(1);
    }
  });

  test("puts the feed beside the floor once the window is wide enough", () => {
    const wide = restaurantArenaLayout(FEED_BESIDE_WIDTH, 700);
    expect(wide.feedBeside).toBe(true);
    // Beside means level with the floor, not under it.
    expect(wide.feed.x).toBeGreaterThan(wide.dining.x);
    expect(wide.feed.y).toBe(wide.kitchen.y);

    const narrow = restaurantArenaLayout(FEED_BESIDE_WIDTH - 1, 700);
    expect(narrow.feedBeside).toBe(false);
    expect(narrow.feed.y).toBeGreaterThanOrEqual(narrow.tickets.y + narrow.tickets.height);
  });

  test("every rect fits inside the window it was given", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      for (const [name, rect] of rects(layout)) {
        const where = `${name} at ${w}x${h}`;
        expect(rect.width, where).toBeGreaterThan(0);
        expect(rect.height, where).toBeGreaterThan(0);
        expect(rect.x, where).toBeGreaterThanOrEqual(0);
        expect(rect.y, where).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, where).toBeLessThanOrEqual(w);
        expect(rect.y + rect.height, where).toBeLessThanOrEqual(h);
      }
    }
  });

  test("the floor bands stack in reading order and never overlap", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      const where = `${w}x${h}`;
      expect(layout.topBar.y + layout.topBar.height, where).toBeLessThanOrEqual(layout.brief.y);
      expect(layout.brief.y + layout.brief.height, where).toBeLessThanOrEqual(layout.kitchen.y);
      expect(layout.kitchen.x + layout.kitchen.width, where).toBeLessThanOrEqual(layout.pass.x);
      expect(layout.pass.x + layout.pass.width, where).toBeLessThanOrEqual(layout.dining.x);
      expect(layout.dining.y + layout.dining.height, where).toBeLessThanOrEqual(layout.door.y);
      expect(layout.kitchen.y + layout.kitchen.height, where).toBeLessThanOrEqual(layout.tickets.y);
    }
  });

  test("the host stand keeps a hittable size at every window size", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      const where = `${w}x${h}`;
      expect(layout.doorStand.width, where).toBeGreaterThanOrEqual(MIN_STAND_WIDTH);
      expect(layout.doorStand.height, where).toBeGreaterThanOrEqual(MIN_STAND_HEIGHT);
    }
  });

  test("the host stand sits inside the door, below its label", () => {
    const layout = restaurantArenaLayout(1024, 768);
    expect(layout.doorStand.x).toBeGreaterThan(layout.door.x);
    expect(layout.doorStand.y).toBeGreaterThan(layout.door.y);
    expect(layout.doorStand.x + layout.doorStand.width).toBeLessThanOrEqual(
      layout.door.x + layout.door.width,
    );
    expect(layout.doorStand.y + layout.doorStand.height).toBeLessThanOrEqual(
      layout.door.y + layout.door.height,
    );
  });

  test("the hallway line runs through the pass zone", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      const where = `${w}x${h}`;
      expect(layout.spineY, where).toBeGreaterThanOrEqual(layout.pass.y);
      expect(layout.spineY, where).toBeLessThanOrEqual(layout.pass.y + layout.pass.height);
    }
  });

  test("waypoints sit in their own zones, with the queue on the host stand", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      const where = `${w}x${h}`;
      const inside = (rect: ArenaRect, point: { x: number; y: number }) =>
        point.x >= rect.x &&
        point.x <= rect.x + rect.width &&
        point.y >= rect.y &&
        point.y <= rect.y + rect.height;
      expect(inside(layout.kitchen, layout.waypoints.kitchen), where).toBe(true);
      expect(inside(layout.pass, layout.waypoints.pass), where).toBe(true);
      expect(inside(layout.dining, layout.waypoints.floor), where).toBe(true);
      expect(inside(layout.doorStand, layout.waypoints.queue), where).toBe(true);
    }
  });

  test("the stations stay in hallway order left to right", () => {
    const layout = restaurantArenaLayout(1280, 800);
    expect(layout.waypoints.kitchen.x).toBeLessThan(layout.waypoints.pass.x);
    expect(layout.waypoints.pass.x).toBeLessThan(layout.waypoints.floor.x);
  });
});

