1	/**
2	 * Staff movement across the Restaurant Arena floor.
3	 *
4	 * Two ideas, and everything here follows from them.
5	 *
6	 * **The floor is a hallway, not a graph of teleports.** Kitchen, pass, dining
7	 * floor and door queue sit in that order along one line, and `WALK_GRAPH`
8	 * wires them that way: the pass and the floor are through-stations, so a chef
9	 * sent from the kitchen to the door *walks past the pass and across the
10	 * dining room* rather than appearing at the door. That is the whole point of
11	 * animating this at all — the player can see the cost of the assignment they
12	 * just made, because the person is out of position for as long as the walk
13	 * takes.
14	 *
15	 * **A walk rides the hallway.** `corridorPoints` never emits a diagonal: it
16	 * steps onto the hallway line (`spineY`, from the layout), travels along it,
17	 * and steps off at the far end. A straight line from the kitchen to the door
18	 * would cut through the middle of the dining room and read as a person
19	 * walking over the tables.
20	 *
21	 * `StaffWalker` owns one person's pixels. It is deliberately free of Phaser:
22	 * the scene creates a container wherever the walker says it is, and the
23	 * walker knows nothing about it. That keeps the movement — the part with the
24	 * arithmetic in it — testable, and it means a repaint (which destroys every
25	 * game object in the scene) can't lose a walk in progress.
26	 */
27	
28	import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";
29	
30	export type WalkNode = ArenaLocation;
31	export type Point = ArenaPoint;
32	
33	/**
34	 * The floor as one hallway: kitchen ── pass ── floor ── queue. Neighbours
35	 * only; nothing skips a station, which is what makes `bfsPath("kitchen",
36	 * "queue")` route through both middles.
37	 */
38	export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
39	  kitchen: ["pass"],
40	  pass: ["kitchen", "floor"],
41	  floor: ["pass", "queue"],
42	  queue: ["floor"],
43	};
44	
45	/** A walking pace, not a teleport and not a shuffle. */
46	export const WALK_SPEED_PX_PER_SEC = 200;
47	
48	/** Below this a hop is treated as "already there" rather than divided by. */
49	const MIN_HOP_MS = 1;
50	
51	/** Snapping tolerance in pixels — layout rounding, not real distance. */
52	const EPSILON = 0.5;
53	
54	/**
55	 * Shortest station-to-station route, inclusive of both ends. `from === to`
56	 * yields the single node.
57	 */
58	export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
59	  if (from === to) return [from];
60	  const previous = new Map<WalkNode, WalkNode>();
61	  const seen = new Set<WalkNode>([from]);
62	  const queue: WalkNode[] = [from];
63	
64	  while (queue.length > 0) {
65	    const node = queue.shift()!;
66	    for (const next of WALK_GRAPH[node]) {
67	      if (seen.has(next)) continue;
68	      seen.add(next);
69	      previous.set(next, node);
70	      if (next === to) {
71	        const path: WalkNode[] = [to];
72	        let cursor: WalkNode = to;
73	        while (cursor !== from) {
74	          cursor = previous.get(cursor)!;
75	          path.unshift(cursor);
76	        }
77	        return path;
78	      }
79	      queue.push(next);
80	    }
81	  }
82	  return [];
83	}
84	
85	/**
86	 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
87	 * hallway instead of cutting diagonally through a room.
88	 *
89	 * Every segment is axis-aligned, and any segment that moves horizontally does
90	 * so *on* the hallway line. `start` itself is not repeated in the result — it
91	 * is where the walker already is.
92	 */
93	export function corridorPoints(
94	  start: Point,
95	  nodes: readonly WalkNode[],
96	  waypoints: Record<WalkNode, Point>,
97	  spineY: number,
98	): Point[] {
99	  const points: Point[] = [];
100	  let cursor: Point = { x: start.x, y: start.y };
101	
102	  const push = (point: Point) => {
103	    if (Math.abs(point.x - cursor.x) < EPSILON && Math.abs(point.y - cursor.y) < EPSILON) return;
104	    points.push(point);
105	    cursor = point;
106	  };
107	
108	  for (const node of nodes) {
109	    const target = waypoints[node];
110	    if (!target) continue;
111	    if (Math.abs(target.x - cursor.x) < EPSILON) {
112	      // Same column already — walking out to the hallway and back would be a
113	      // detour, not a route.
114	      push({ x: cursor.x, y: target.y });
115	      continue;
116	    }
117	    if (Math.abs(cursor.y - spineY) >= EPSILON) push({ x: cursor.x, y: spineY });
118	    push({ x: target.x, y: spineY });
119	    if (Math.abs(target.y - spineY) >= EPSILON) push({ x: target.x, y: target.y });
120	  }
121	
122	  return points;
123	}
124	
125	/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
126	export function hopDurationMs(from: Point, to: Point): number {
127	  const distance = Math.hypot(to.x - from.x, to.y - from.y);
128	  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
129	}
130	
131	/** Smoothstep, so each leg of the walk starts and stops like a person. */
132	function ease(t: number): number {
133	  const clamped = Math.min(1, Math.max(0, t));
134	  return clamped * clamped * (3 - 2 * clamped);
135	}
136	
137	export class StaffWalker {
138	  x: number;
139	  y: number;
140	  facing: 1 | -1 = 1;
141	  walking = false;
142	  /** Set by the scene while the player is holding this person; freezes the walk. */
143	  dragging = false;
144	  node: WalkNode;
145	
146	  /** Remaining hops, in order. `path[0]` is the leg currently in progress. */
147	  private path: Point[] = [];
148	  /** Where the current leg started — the interpolation origin. */
149	  private origin: Point;
150	  private hopMs = 0;
151	  private elapsed = 0;
152	
153	  /** `slot` is the pixel position of `node`; the walker starts parked there. */
154	  constructor(node: WalkNode, slot: Point) {
155	    this.node = node;
156	    this.x = slot.x;
157	    this.y = slot.y;
158	    this.origin = { x: slot.x, y: slot.y };
159	  }
160	
