/**
 * Staff movement across the Restaurant Arena floor.
 *
 * Two ideas, and everything here follows from them.
 *
 * **The floor is a hallway, not a graph of teleports.** Kitchen, pass, dining
 * floor and door queue sit in that order along one line, and `WALK_GRAPH`
 * wires them that way: the pass and the floor are through-stations, so a chef
 * sent from the kitchen to the door *walks past the pass and across the
 * dining room* rather than appearing at the door. That is the whole point of
 * animating this at all — the player can see the cost of the assignment they
 * just made, because the person is out of position for as long as the walk
 * takes.
 *
 * **A walk rides the hallway.** `corridorPoints` never emits a diagonal: it
 * steps onto the hallway line (`spineY`, from the layout), travels along it,
 * and steps off at the far end. A straight line from the kitchen to the door
 * would cut through the middle of the dining room and read as a person
 * walking over the tables.
 *
 * `StaffWalker` owns one person's pixels. It is deliberately free of Phaser:
 * the scene creates a container wherever the walker says it is, and the
 * walker knows nothing about it. That keeps the movement — the part with the
 * arithmetic in it — testable, and it means a repaint (which destroys every
 * game object in the scene) can't lose a walk in progress.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * The floor as one hallway: kitchen ── pass ── floor ── queue. Neighbours
 * only; nothing skips a station, which is what makes `bfsPath("kitchen",
 * "queue")` route through both middles.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** A walking pace, not a teleport and not a shuffle. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Below this a hop is treated as "already there" rather than divided by. */
const MIN_HOP_MS = 1;

/** Snapping tolerance in pixels — layout rounding, not real distance. */
const EPSILON = 0.5;

/**
 * Shortest station-to-station route, inclusive of both ends. `from === to`
 * yields the single node.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];

  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node]) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let cursor: WalkNode = to;
        while (cursor !== from) {
          cursor = previous.get(cursor)!;
          path.unshift(cursor);
        }
        return path;
      }
      queue.push(next);
    }
  }
  return [];
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Every segment is axis-aligned, and any segment that moves horizontally does
 * so *on* the hallway line. `start` itself is not repeated in the result — it
 * is where the walker already is.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let cursor: Point = { x: start.x, y: start.y };

  const push = (point: Point) => {
    if (Math.abs(point.x - cursor.x) < EPSILON && Math.abs(point.y - cursor.y) < EPSILON) return;
    points.push(point);
    cursor = point;
  };

  for (const node of nodes) {
    const target = waypoints[node];
    if (!target) continue;
    if (Math.abs(target.x - cursor.x) < EPSILON) {
      // Same column already — walking out to the hallway and back would be a
      // detour, not a route.
      push({ x: cursor.x, y: target.y });
      continue;
    }
    if (Math.abs(cursor.y - spineY) >= EPSILON) push({ x: cursor.x, y: spineY });
    push({ x: target.x, y: spineY });
    if (Math.abs(target.y - spineY) >= EPSILON) push({ x: target.x, y: target.y });
  }

  return points;
}

/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/** Smoothstep, so each leg of the walk starts and stops like a person. */
function ease(t: number): number {
  const clamped = Math.min(1, Math.max(0, t));
  return clamped * clamped * (3 - 2 * clamped);
}

export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  /** Set by the scene while the player is holding this person; freezes the walk. */
  dragging = false;
  node: WalkNode;

  /** Remaining hops, in order. `path[0]` is the leg currently in progress. */
  private path: Point[] = [];
  /** Where the current leg started — the interpolation origin. */
  private origin: Point;
  private hopMs = 0;
  private elapsed = 0;

  /** `slot` is the pixel position of `node`; the walker starts parked there. */
  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
    this.origin = { x: slot.x, y: slot.y };
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
  snap(slot: Point, node: WalkNode): void {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
    this.origin = { x: slot.x, y: slot.y };
    this.path = [];
    this.walking = false;
    this.hopMs = 0;
    this.elapsed = 0;
  }

  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    const destination = waypoints[target];
    if (!destination) return;
    if (target === this.node) {
      // Already assigned here: either still walking in (leave the walk alone —
      // the scene calls this on every repaint) or already parked.
      if (this.walking) return;
      if (
        Math.abs(this.x - destination.x) < EPSILON &&
        Math.abs(this.y - destination.y) < EPSILON
      ) {
        return;
      }
    }

    const route = bfsPath(this.node, target);
    // Drop the station we are standing in; the walk starts from the pixel we
    // are actually on, which may be an offset slot rather than its centre.
    const nodes = route[0] === this.node ? route.slice(1) : route;
    const path = corridorPoints({ x: this.x, y: this.y }, nodes.length > 0 ? nodes : [target], waypoints, spineY);

    // The assignment lands now; the walk is how it looks, not whether it took.
    this.node = target;
    this.path = path;
    this.origin = { x: this.x, y: this.y };
    this.elapsed = 0;
    this.walking = path.length > 0;
    this.beginHop();
  }

  /**
   * Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns
   * whether the pixel position changed.
   */
  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking) return false;
    const delta = dtMs * speed;
    if (!Number.isFinite(delta) || delta <= 0) return false;

    const startX = this.x;
    const startY = this.y;
    this.elapsed += delta;

    // A single frame at 4× can span more than one short hop, so leftover time
    // carries into the next leg instead of being dropped at each corner.
    while (this.walking) {
      const next = this.path[0];
      if (!next) {
        this.finish();
        break;
      }
      if (this.hopMs < MIN_HOP_MS || this.elapsed >= this.hopMs) {
        this.elapsed = this.hopMs < MIN_HOP_MS ? this.elapsed : this.elapsed - this.hopMs;
        this.x = next.x;
        this.y = next.y;
        this.origin = next;
        this.path.shift();
        if (this.path.length === 0) {
          this.finish();
          break;
        }
        this.beginHop();
        continue;
      }
      const eased = ease(this.elapsed / this.hopMs);
      this.x = this.origin.x + (next.x - this.origin.x) * eased;
      this.y = this.origin.y + (next.y - this.origin.y) * eased;
      break;
    }

    return this.x !== startX || this.y !== startY;
  }

  private beginHop(): void {
    const next = this.path[0];
    if (!next) {
      this.hopMs = 0;
      return;
    }
    this.hopMs = hopDurationMs(this.origin, next);
    // Face where the walk is going. A vertical leg keeps the previous facing
    // rather than snapping the sprite to some default.
    if (next.x > this.origin.x + EPSILON) this.facing = 1;
    else if (next.x < this.origin.x - EPSILON) this.facing = -1;
  }

  private finish(): void {
    this.path = [];
    this.walking = false;
    this.hopMs = 0;
    this.elapsed = 0;
  }
}

