import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const layout = restaurantArenaLayout(520, 740);
const waypoints = layout.waypoints;
const spineY = layout.spineY;

/** Total straight-line length of a chain of points. */
function pathLength(start: Point, points: readonly Point[]): number {
  let total = 0;
  let cursor = start;
  for (const point of points) {
    total += Math.hypot(point.x - cursor.x, point.y - cursor.y);
    cursor = point;
  }
  return total;
}

describe("walk graph", () => {
  test("wires the floor as one hallway with neighbours only", () => {
    expect(WALK_GRAPH.kitchen).toEqual(["pass"]);
    expect(WALK_GRAPH.queue).toEqual(["floor"]);
    expect([...WALK_GRAPH.pass].sort()).toEqual(["floor", "kitchen"]);
    expect([...WALK_GRAPH.floor].sort()).toEqual(["pass", "queue"]);
  });

  test("adjacency is symmetric, so every walk can be walked back", () => {
    for (const node of Object.keys(WALK_GRAPH) as WalkNode[]) {
      for (const neighbour of WALK_GRAPH[node]) {
        expect(WALK_GRAPH[neighbour]).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  test("kitchen to queue routes through both through-stations", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
  });

  test("routes back the other way in reverse", () => {
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  test("includes both ends for a single hop", () => {
    expect(bfsPath("kitchen", "pass")).toEqual(["kitchen", "pass"]);
    expect(bfsPath("floor", "queue")).toEqual(["floor", "queue"]);
  });

  test("a station to itself is a path of one", () => {
    for (const node of Object.keys(WALK_GRAPH) as WalkNode[]) {
      expect(bfsPath(node, node)).toEqual([node]);
    }
  });

  test("every pair is reachable and never skips a station", () => {
    const nodes = Object.keys(WALK_GRAPH) as WalkNode[];
    for (const from of nodes) {
      for (const to of nodes) {
        const path = bfsPath(from, to);
        expect(path.length, `${from}->${to}`).toBeGreaterThan(0);
        expect(path[0], `${from}->${to}`).toBe(from);
        expect(path[path.length - 1], `${from}->${to}`).toBe(to);
        for (let i = 1; i < path.length; i += 1) {
          expect(WALK_GRAPH[path[i - 1]!], `${from}->${to} step ${i}`).toContain(path[i]!);
        }
      }
    }
  });
});

describe("corridorPoints", () => {
  test("never emits a diagonal, and travels sideways only on the hallway line", () => {
    const routes: [WalkNode, WalkNode][] = [
      ["kitchen", "queue"],
      ["queue", "kitchen"],
      ["kitchen", "floor"],
      ["floor", "kitchen"],
      ["pass", "queue"],
      ["queue", "pass"],
    ];
    for (const [from, to] of routes) {
      const start = waypoints[from];
      const nodes = bfsPath(from, to).slice(1);
      const points = corridorPoints(start, nodes, waypoints, spineY);
      let cursor = start;
      for (const point of points) {
        const movedX = Math.abs(point.x - cursor.x) > 0.5;
        const movedY = Math.abs(point.y - cursor.y) > 0.5;
        expect(movedX && movedY, `${from}->${to} diagonal segment`).toBe(false);
        if (movedX) {
          expect(cursor.y, `${from}->${to} sideways off the hallway`).toBe(spineY);
          expect(point.y, `${from}->${to} sideways off the hallway`).toBe(spineY);
        }
        cursor = point;
      }
      expect(cursor.x, `${from}->${to} endpoint`).toBeCloseTo(waypoints[to].x, 5);
      expect(cursor.y, `${from}->${to} endpoint`).toBeCloseTo(waypoints[to].y, 5);
    }
  });

  test("a kitchen to queue walk passes the pass and crosses the dining room", () => {
    const nodes = bfsPath("kitchen", "queue").slice(1);
    const points = corridorPoints(waypoints.kitchen, nodes, waypoints, spineY);
    const xs = points.map((point) => point.x);
    expect(xs).toContain(waypoints.pass.x);
    expect(xs).toContain(waypoints.floor.x);
    // Longer than the straight line it deliberately refuses to take.
    const direct = Math.hypot(
      waypoints.queue.x - waypoints.kitchen.x,
      waypoints.queue.y - waypoints.kitchen.y,
    );
    expect(pathLength(waypoints.kitchen, points)).toBeGreaterThan(direct);
  });

  test("a straight walk down the same column stays in that column", () => {
    const start: Point = { x: waypoints.floor.x, y: spineY };
    const points = corridorPoints(start, ["floor"], waypoints, spineY);
    expect(points).toEqual([{ x: waypoints.floor.x, y: waypoints.floor.y }]);
  });

  test("drops zero-length hops instead of emitting a stall", () => {
    expect(corridorPoints(waypoints.pass, ["pass"], waypoints, spineY)).toEqual([]);
  });
});

describe("hopDurationMs", () => {
  test("walks at 200px per second", () => {
    expect(WALK_SPEED_PX_PER_SEC).toBe(200);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 200, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBe(500);
    expect(hopDurationMs({ x: 10, y: 10 }, { x: 310, y: 410 })).toBe(2500);
  });

  test("standing still takes no time", () => {
    expect(hopDurationMs({ x: 42, y: 7 }, { x: 42, y: 7 })).toBe(0);
  });
});

describe("StaffWalker", () => {
  const parked = () => new StaffWalker("kitchen", waypoints.kitchen);

  test("starts parked on its slot", () => {
    const walker = parked();
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
    expect(walker.node).toBe("kitchen");
    expect(walker.walking).toBe(false);
    expect(walker.dragging).toBe(false);
    expect(walker.facing).toBe(1);
  });

  test("a fresh target starts a walk and takes the assignment immediately", () => {
    const walker = parked();
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.node).toBe("queue");
    expect(walker.walking).toBe(true);
    // Still standing in the kitchen, though — the walk is the cost.
    expect(walker.x).toBe(waypoints.kitchen.x);
  });

  test("re-targeting the station it is parked in is a no-op", () => {
    const walker = parked();
    walker.setTarget("kitchen", waypoints, spineY);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
  });

  test("arrives on the destination slot and stops walking", () => {
    const walker = parked();
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.step(60_000, 1)).toBe(true);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
    expect(walker.step(16, 1)).toBe(false);
  });

  test("arrives in about the time the distance implies at 200px/s", () => {
    const walker = parked();
    const nodes = bfsPath("kitchen", "queue").slice(1);
    const expected =
      (pathLength(waypoints.kitchen, corridorPoints(waypoints.kitchen, nodes, waypoints, spineY)) /
        WALK_SPEED_PX_PER_SEC) *
      1000;

    walker.setTarget("queue", waypoints, spineY);
    let elapsed = 0;
    while (walker.walking && elapsed < 30_000) {
      walker.step(16, 1);
      elapsed += 16;
    }
    expect(walker.walking).toBe(false);
    expect(elapsed).toBeGreaterThanOrEqual(expected - 16);
    expect(elapsed).toBeLessThanOrEqual(expected + 32);
  });

  test("eases each hop instead of moving at a constant rate", () => {
    const walker = new StaffWalker("pass", { x: 100, y: spineY });
    const straight: Record<WalkNode, Point> = {
      ...waypoints,
      pass: { x: 100, y: spineY },
      floor: { x: 500, y: spineY },
    };
    walker.setTarget("floor", straight, spineY);

    const hopMs = hopDurationMs({ x: 100, y: spineY }, { x: 500, y: spineY });
    walker.step(hopMs * 0.25, 1);
    // Smoothstep: a quarter of the way through the hop covers well under a
    // quarter of the distance.
    expect(walker.x).toBeLessThan(100 + 400 * 0.25);
    expect(walker.x).toBeGreaterThan(100);

    walker.step(hopMs * 0.25, 1);
    expect(walker.x).toBeCloseTo(300, 5);
  });

  test("speed scales the walk, and zero speed pauses it without cancelling", () => {
    const walker = parked();
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.step(16, 0)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.walking).toBe(true);

    const fast = parked();
    fast.setTarget("queue", waypoints, spineY);
    const slow = parked();
    slow.setTarget("queue", waypoints, spineY);
    fast.step(100, 4);
    slow.step(100, 1);
    expect(Math.abs(fast.x - waypoints.kitchen.x)).toBeGreaterThan(
      Math.abs(slow.x - waypoints.kitchen.x),
    );
  });

  test("a drag freezes the walk while it is held", () => {
    const walker = parked();
    walker.setTarget("queue", waypoints, spineY);
    walker.dragging = true;
    expect(walker.step(1000, 1)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);
    walker.dragging = false;
    expect(walker.step(1000, 1)).toBe(true);
  });

  test("faces the direction of travel", () => {
    const outbound = parked();
    outbound.setTarget("queue", waypoints, spineY);
    outbound.step(60_000, 1);
    expect(outbound.facing).toBe(1);

    outbound.setTarget("kitchen", waypoints, spineY);
    outbound.step(60_000, 1);
    expect(outbound.facing).toBe(-1);
  });

  test("snap teleports, adopts the node and drops any walk in progress", () => {
    const walker = parked();
    walker.setTarget("queue", waypoints, spineY);
    walker.step(50, 1);
    walker.snap(waypoints.floor, "floor");
    expect(walker.node).toBe("floor");
    expect(walker.x).toBe(waypoints.floor.x);
    expect(walker.y).toBe(waypoints.floor.y);
    expect(walker.walking).toBe(false);
    expect(walker.step(1000, 1)).toBe(false);
  });

  test("a new target mid-walk reroutes from the pixel it is standing on", () => {
    const walker = parked();
    walker.setTarget("queue", waypoints, spineY);
    walker.step(200, 1);
    const midX = walker.x;
    walker.setTarget("kitchen", waypoints, spineY);
    expect(walker.node).toBe("kitchen");
    expect(walker.x).toBe(midX);
    walker.step(60_000, 1);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
  });

  test("walks to an offset slot rather than the zone centre", () => {
    const slot: Point = { x: waypoints.floor.x + 18, y: waypoints.floor.y + 6 };
    const walker = parked();
    walker.setTarget("floor", { ...waypoints, floor: slot }, spineY);
    walker.step(60_000, 1);
    expect(walker.x).toBe(slot.x);
    expect(walker.y).toBe(slot.y);
  });
});

