import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints immediately when no drag is open", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
  });

  test("holds paints back while a drag is open", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
  });

  test("owes exactly one repaint no matter how many were held", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    for (let i = 0; i < 12; i += 1) gate.requestPaint();
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    // The owed paint has been handed out; it is not owed twice.
    expect(gate.endDrag()).toBe(false);
  });

  test("owes nothing when a drag passed without a tick", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("reopens for the next drag with a clean slate", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    expect(gate.endDrag()).toBe(true);

    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("paints normally again once the drag has ended", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    gate.endDrag();
    expect(gate.requestPaint()).toBe(true);
  });

  test("resize drops the open drag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a stray dragend after a resize owes nothing", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.endDrag()).toBe(false);
  });

  test("resize with no drag open is harmless", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.endDrag()).toBe(false);
  });

  test("the drop sequence a drag actually runs: one held tick, one replay", () => {
    const gate = new RepaintGate();
    let paints = 0;
    const paint = () => {
      if (gate.requestPaint()) paints += 1;
    };

    paint(); // pre-drag state tick
    expect(paints).toBe(1);

    gate.beginDrag();
    paint(); // sim tick while the token is held
    paint(); // the reassignment dispatched on drop, still inside the drag
    expect(paints).toBe(1);

    if (gate.endDrag()) paints += 1;
    expect(paints).toBe(2);
  });
});

