  walker.setTarget("kitchen", waypoints, spineY);
  walker.step(60_000, 1);
  expect(walker.facing).toBe(-1);
});

test("a purely vertical hop keeps the facing it had", () => {
  const walker = new StaffWalker("floor", { x: waypoints.floor.x, y: spineY });
  walker.facing = -1;
  walker.setTarget("floor", waypoints, spineY);
  walker.step(60_000, 1);
  expect(walker.y).toBe(waypoints.floor.y);
  expect(walker.facing).toBe(-1);
});

